        r = rows[i]
        cat = (r.get(0) or "").strip()
        sub = (r.get(1) or "").strip()
        amt = to_num(r.get(2))
        if amt is None:
            continue
        total += amt
        categories.setdefault(cat, 0.0)
        categories[cat] += amt
        print(f"  {cat:16s} {sub:16s} {amt:,.2f}")

    print("\nSubtotals by category:")
    for cat, amt in sorted(categories.items()):
        print(f"  {cat:16s} {amt:,.2f}")

    print(f"\nTOTAL EXPENSES: {total:,.2f}")

if __name__ == "__main__":
    main(sys.argv[1])
